    #Node Map Range
    def interpolate(
        self,
        to_min: Float = None,
        to_max: Float = None,
        clamp: bool = True,
        interpolation_type: T_INTERPOLATION_TYPE_1 = 'LINEAR'):
        """Node Map Range.
        
        Jump: False
        
        **Fixed inputs**
        - Node parameter 'data_type' = 'FLOAT'
        - Socket 'From Min' = 0.0
        - Socket 'From Max' = 1.0
        - Socket 'Steps' = None
        
        Parameters
        ----------
        interpolation_type : {'LINEAR', 'STEPPED', 'SMOOTHSTEP', 'SMOOTHERSTEP'}, optional
            Node parameter 'interpolation_type' (default: 'LINEAR')
        clamp : VALUE, optional
            Node parameter 'clamp' (default: True)
        to_min : Float, optional
            Socket 'To Min' (default: None)
        to_max : Float, optional
            Socket 'To Max' (default: None)
        

        Returns
        -------
        Socket
            Default output socket.
        """
        node = Node(
            'Map Range',
            named_sockets={'ID_Value': self, 'ID_From Min': 0.0, 'ID_From Max': 1.0, 'ID_To Min': to_min, 'ID_To Max': to_max, 'ID_Steps': None},
            interpolation_type=interpolation_type,
            data_type='FLOAT',
            clamp=clamp)
        
        return node._out
